      "Bash(journalctl:*)",
      "Bash(zfs list:*)",
      "WebSearch",
      "WebFetch(domain:github.com)"
    ],
    "deny": [
      "Bash(git push --force *)",
      "Bash(git push -f *)",
      "Bash(git reset --hard*)",
      "Bash(git clean -fd*)",
      "Bash(git clean -f *)",
      "Bash(rm -rf /*)",
      "Bash(rm -rf ~*)",
      "Bash(sudo rm -rf:*)",
      "Bash(nvidia-smi:*)",
      "Read(./.entire/metadata/**)"
    ]
  }
}

